    eq('apartados plegados por defecto', pg.evaluate("[...document.querySelectorAll('#cfg details.cs')].map(d => [d.querySelector('summary').textContent, d.open])"), [['Paleta de colores', False], ['Estilos de cita personalizados', False], ['Plantillas de nota', False], ['Atajos de teclado', False]])
